contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We accept funds so we can forward them to c when testing value transfer.
    receive() external payable {}

    // Test: send arbitrary amount and simulate calling fallback; assert general invariant about state change
    function run(uint amount, uint beforeRead) public payable {
        // must have enough balance here to forward 'amount'
        require(address(this).balance >= amount);
        // Read observable before-values
        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool reverted;
        // make the state-changing call to fallback by sending value (no data)
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (only public observable) — even if reverted these are valid
        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // General rule asserted:
        // If call did not revert then pastBlockTime must have been updated to a timestamp >= previous value,
        // and the contract balance either increased by exactly amount (normal case) or became zero (withdrawal on block multiple of 15).
        assert(
            reverted || (
                // pastBlockTime non-decreasing and changed to current pastAfter
                pastAfter >= pastBefore
                // balance either increased by amount or is zero
                && (balAfter == balBefore + amount || balAfter == 0)
            )
        );
    }
}

