        require(address(this).balance >= amount);

        // read observables before the call
        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool reverted;
        // make the state-changing call to C's fallback by using address(c).call with empty data
        (bool ok,) = address(c).call{value: amount}("");
        reverted = !ok;

        // read observables after the call
        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // Assert the general rule: if the call did not revert then pastBlockTime is non-decreasing
        // and the contract balance either increased by exactly amount or became zero (withdrawal case)
        assert(reverted || (pastAfter >= pastBefore && (balAfter == balBefore + amount || balAfter == 0)));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    // single public property test
    function run(uint sendAmount) public payable {
        // We will only test the behavior when the caller sends exactly 10 ether to C, as required by C's fallback.
        // Ensure this contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // We only consider the interesting case when sendAmount == 10 ether
        // For other amounts the fallback is expected to revert; the assertion will allow that.
        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool reverted;
        // State-changing call must be a direct top-level call on c. Call the fallback by invoking payable with empty calldata.
        // Use try/catch to capture revert without nesting the call inside other constructs.
        try c.f{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // General rule: if the call with this sendAmount did not revert and sendAmount == 10 ether,
        // then pastBlockTime is non-decreasing and balance either increased by sendAmount or became zero
        assert(reverted || (sendAmount == 10 ether && pastAfter >= pastBefore && (balAfter == balBefore + sendAmount || balAfter == 0)));
    }

    // Provide a payable fallback so try c.f{value:...}() compiles; this is unused.
    fallback() external payable {}
}

