contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will send `amount` wei to c by invoking its fallback. The rule checks effects on pastBlockTime and balance.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // call fallback by sending Ether with no data
        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // General rule:
        // - If the call reverted, then nothing about c's state is required (call may revert for many reasons).
        // - If the call did not revert and amount == 10 ether and block.timestamp > beforePast then:
        //     * pastBlockTime must have been updated to the (non-decreasing) afterPast >= beforePast and equal to current block.timestamp
        //     * if block.number % 15 == 0 then the contract should have sent its entire balance away (afterBalance == 0)
        //       else the contract balance should be exactly beforeBalance + 10 ether.
        // We cannot read block.timestamp inside the expression, so require the implications only when we see the observable state changes.

        // Encode the implication as a single boolean expression for assert:
        // If not reverted and amount==10 ether and afterPast > beforePast then:
        //    ( (block.number % 15 == 0) ? afterBalance == 0 : afterBalance == beforeBalance + 10 ether )
        //    and afterPast >= beforePast
        // Otherwise assert vacuously true.

        bool cond = true;
        if (!reverted && amount == 10 ether && afterPast > beforePast) {
            bool balOk;
            if (block.number % 15 == 0) {
                balOk = (afterBalance == 0);
            } else {
                balOk = (afterBalance == beforeBalance + 10 ether);
            }
            cond = (afterPast >= beforePast) && balOk;
        }

        assert(cond);
    }

    // allow receiving refunds if contract C transfers Ether to this test
    receive() external payable {}
}

